'use strict';
const STORE='smech_mvp_v01'; // keep the original key to migrate existing 0.1 data
const VIEWS={dashboard:['Обзор','Рабочий стол'],projects:['Объекты','Объекты'],vor:['Ведомость работ','Ведомость объёмов работ'],materials:['Материалы','Потребность в материалах'],labor:['Оплата СМР','Оплата строительно-монтажных работ'],estimate:['Коммерческий расчёт','Экономика объекта'],catalog:['Справочник материалов','Справочник материалов'],spec:['Спецификации','Сверка материалов'],approvals:['Согласование','Проверка и утверждение'],history:['История версий','Зафиксированные расчёты'],settings:['Настройки','Настройки и резервные копии']};
const units=['м','м²','м³','шт','т','кг','л','компл','п.м.'];
const uid=()=>Math.random().toString(36).slice(2,10)+Date.now().toString(36);
const today=()=>{const d=new Date();return [d.getFullYear(),String(d.getMonth()+1).padStart(2,'0'),String(d.getDate()).padStart(2,'0')].join('-');};
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const rub=x=>new Intl.NumberFormat('ru-RU',{style:'currency',currency:'RUB',maximumFractionDigits:2}).format(Number(x)||0);
const qtyFmt=x=>new Intl.NumberFormat('ru-RU',{maximumFractionDigits:3}).format(Number(x)||0);
const inputNum=x=>{let v=String(x??'').trim().replace(/[\u00a0\u202f]/g,' ');if(v.includes(' ')){if(!/^\d{1,3}(?: \d{3})+(?:[.,]\d+)?$/.test(v))return v;v=v.replace(/ /g,'');}return v.replace(',', '.');};
const isNumber=x=>{const n=inputNum(x);return /^\d+(?:\.\d{1,12})?$/.test(n)&&Number.isFinite(Number(n))&&Number(n)<=1e12;};
const option=(v,selected)=>`<option value="${esc(v)}" ${v===selected?'selected':''}>${esc(v)}</option>`;
let storageLocked=false,loadError='',data=load(),view='dashboard',calc=null,importData=null,sortDir=1;
function seed(){
 const mats=[
 ['Грунтовка глубокого проникновения','л',180],['Штукатурная сухая смесь','кг',19],['Гипсокартон','м²',310],['Профиль металлический','м',110],['Краска интерьерная','л',410],['Плитка напольная','м²',1200],['Клей плиточный','кг',26],['Дверной блок','шт',12000]
 ].map((a,i)=>({id:'demo-m'+i,name:a[0],unit:a[1],price:a[2],date:'',source:'Условные демоданные'}));
 const mk=(name,unit,qty,rate,section,resources)=>({id:uid(),code:'',section,name,unit,qty,laborRate:rate,materialRequired:true,source:'Демонстрационный пример',note:'',materials:resources.map(r=>({id:uid(),materialId:mats[r[0]].id,norm:r[1],waste:r[2]}))});
 const lines=[
 mk('Грунтовка стен','м²',120,75,'Отделка',[[0,.15,5]]),
 mk('Штукатурка стен','м²',120,480,'Отделка',[[1,8,7]]),
 mk('Монтаж перегородок из ГКЛ','м²',52,650,'Перегородки',[[2,2.1,10],[3,3.5,5]]),
 mk('Окраска стен','м²',120,300,'Отделка',[[4,.18,10]]),
 mk('Укладка напольной плитки','м²',40,950,'Полы',[[5,1,8],[6,5,5]]),
 mk('Установка дверных блоков','шт',4,4000,'Проёмы',[[7,1,0]])
 ];
 const project={id:uid(),specifications:[],name:'Демонстрация: ремонт помещения',address:'',organization:'',date:today(),version:1,demo:true,lines,extras:{machinery:5000,delivery:8000,other:2000,employmentChargesPct:0,overheadPct:10,markupPct:15,vatMode:'none',vatPct:0}};
 return {projects:[project],active:project.id,catalog:mats};
}
function validId(x){return typeof x==='string' && /^[a-zA-Z0-9_:-]{1,100}$/.test(x);}
function slim(x,max=300){return String(x??'').slice(0,max);}
function normalizeData(raw){
 if(!raw||!Array.isArray(raw.projects)||!Array.isArray(raw.catalog)||!raw.projects.length||raw.projects.length>200||raw.catalog.length>5000)throw Error('Ошибка структуры объектов или справочника');
 const mids=new Set(),pids=new Set();
 const catalog=raw.catalog.map(m=>{if(!m||!validId(m.id)||mids.has(m.id))throw Error('Некорректный идентификатор материала');mids.add(m.id);
  return {id:m.id,name:slim(m.name),unit:slim(m.unit,30),price:m.price??null,date:slim(m.date,30),source:slim(m.source,500)};});
 const mById=new Map(catalog.map(m=>[m.id,m]));
 const projects=raw.projects.map(p=>{if(!p||!validId(p.id)||pids.has(p.id)||!Array.isArray(p.lines)||p.lines.length>10000)throw Error('Некорректный объект или слишком большая ВОР');pids.add(p.id);
  const lineIds=new Set();const lines=p.lines.map(l=>{if(!l||!validId(l.id)||lineIds.has(l.id)||!Array.isArray(l.materials||[])||l.materials.length>200)throw Error('Повреждена позиция ВОР');lineIds.add(l.id);
   const links=l.materials.map(a=>{if(!a||!validId(a.id)||typeof a.materialId!=='string'||a.materialId.length>100)throw Error('Повреждена привязка материала');const m=mById.get(a.materialId)||{};
    return {id:a.id,materialId:a.materialId,norm:a.norm??null,waste:a.waste??0,
      // Freeze old v0.1 links on upgrade: subsequent catalog changes cannot alter the estimate.
      materialName:slim(a.materialName??m.name),materialUnit:slim(a.materialUnit??m.unit,30),
      price:Object.hasOwn(a,'price')?a.price:m.price??null,priceSource:slim(a.priceSource??m.source,500),priceDate:slim(a.priceDate??m.date,30)};});
   return {id:l.id,name:slim(l.name,500),section:slim(l.section,200),code:slim(l.code,150),unit:slim(l.unit,50),qty:l.qty??null,
      source:slim(l.source,500),sourceRef:normalizeSourceRef(l.sourceRef),note:slim(l.note,1000),laborRate:l.laborRate??null,laborSource:slim(l.laborSource,500),laborDate:slim(l.laborDate,30),materialRequired:l.materialRequired===null?null:!!l.materialRequired,materials:links};});
  const extra=p.extras||{};let snaps=Array.isArray(p.snapshots)?p.snapshots.slice(-12):[];
  snaps=snaps.filter(x=>x&&validId(x.id)&&typeof x.at==='string'&&x.summary&&typeof x.summary==='object').map(x=>({id:x.id,at:slim(x.at,80),version:Number(x.version)||1,status:slim(x.status,40),summary:x.summary,project:x.project||null,blockers:Array.isArray(x.blockers)?x.blockers.slice(0,100):[]}));
  return {id:p.id,specifications:normalizeSpecifications(p.specifications||[]),name:slim(p.name,400),address:slim(p.address,400),organization:slim(p.organization,300),date:slim(p.date,30),version:Number(p.version)||1,demo:!!p.demo,lines,
   extras:{machinery:extra.machinery??0,delivery:extra.delivery??0,other:extra.other??0,employmentChargesPct:extra.employmentChargesPct??0,overheadPct:extra.overheadPct??0,markupPct:extra.markupPct??0,vatPct:extra.vatPct??0,vatMode:extra.vatMode??(Number(extra.vatPct)>0?'rate':'none')},snapshots:snaps};});
 return {projects,active:pids.has(raw.active)?raw.active:projects[0].id,catalog};
}
function normalizeSourceRef(x){if(!x||typeof x!=='object'||!/^([0-9a-f]{64})$/.test(String(x.sha256||'')))return null;
 const validBox=Array.isArray(x.rowBbox)&&x.rowBbox.length===4&&x.rowBbox.every(v=>typeof v==='number'&&Number.isFinite(v)&&v>=0&&v<20000);
 return {sha256:x.sha256,file:slim(x.file,120),page:Math.min(40,Math.max(1,Number(x.page)||1)),table:Math.max(1,Number(x.table)||1),row:Math.max(1,Number(x.row)||1),rowBbox:validBox?x.rowBbox:null};}
function normalizeSpecifications(xs){if(!Array.isArray(xs)||xs.length>10000)throw Error('Повреждена спецификация');const seen=new Set();return xs.map(x=>{if(!x||!validId(x.id)||seen.has(x.id)||!isNumber(x.qty)||Number(inputNum(x.qty))<=0||!String(x.name||'').trim()||!String(x.unit||'').trim())throw Error('Повреждена строка спецификации');seen.add(x.id);return {id:x.id,name:slim(x.name,500),unit:slim(x.unit,40),qty:inputNum(x.qty),code:slim(x.code,120),source:slim(x.source,500),note:slim(x.note,1000)};});}
function load(){let saved;try{saved=localStorage.getItem(STORE);}catch(e){storageLocked=true;loadError='Доступ к хранилищу браузера ограничен';return seed();}if(saved===null)return seed();try{return normalizeData(JSON.parse(saved));}catch(e){storageLocked=true;loadError=e.message;return seed();}}
function save(){if(window.smechWorkspace?.active){window.smechWorkspace.queue();return true;}if(storageLocked){toast('Автосохранение заблокировано: резервная копия повреждена');return false;}try{localStorage.setItem(STORE,JSON.stringify(data));return true;}catch(e){toast('Недостаточно памяти браузера. Экспортируйте резервную копию JSON.');return false;}}
const project=()=>data.projects.find(p=>p.id===data.active)||data.projects[0];
const lineById=id=>project().lines.find(x=>x.id===id);
const materialById=id=>data.catalog.find(x=>x.id===id);
function toast(message){let t=document.getElementById('toast');t.textContent=message;t.classList.add('show');setTimeout(()=>t.classList.remove('show'),3900);}
function alertBox(){let p=project();let out=window.smechWorkspace?.noticeHtml()||'';if(storageLocked&&!window.smechWorkspace?.active)out+=`<div class="alert"><b>Ошибка исходных сохранённых данных:</b> ${esc(loadError)}. Автосохранение остановлено, чтобы не затереть старые данные. <button class="btn tiny" data-action="downloadDamaged">Скачать исходную копию</button> <button class="btn tiny danger" data-action="resetDamaged">Начать заново</button></div>`;if(p.demo)out+=`<div class="alert"><b>Демонстрационные данные.</b> Все объёмы, цены, нормы и ставки в этом объекте вымышленные. Для реальной работы создайте новый объект и заполните данные из своих документов.</div>`;
 if(calc?.issues?.length)out+=`<div class="alert"><b>${calc.blockers?.length||0} блокирующих замечаний и ${calc.warnings?.length||0} предупреждений.</b> Отсутствующие значения не оценены автоматически. <button class="btn tiny" data-view="estimate">Просмотреть расчёт</button></div>`;
 return out;
}
function head(title,subtitle,actions=''){return `<div class="page-head"><div><h1>${title}</h1><p class="subtitle">${subtitle}</p></div><div class="actions">${actions}</div></div>`;}
function metric(label,val,sub='',strong=false){return `<div class="metric ${strong?'strong':''}"><div class="metric-label">${label}</div><div class="metric-value">${val}</div><div class="metric-foot">${sub}</div></div>`;}
function panel(title,sub,content,right=''){return `<section class="panel"><div class="panel-header"><div><div class="panel-title">${title}</div>${sub?`<div class="panel-sub">${sub}</div>`:''}</div>${right}</div>${content}</section>`;}
function empty(text,button=''){return `<div class="empty"><h3>Пока нет данных</h3><p>${text}</p>${button}</div>`;}
function moneyCells(summary){const s=summary||{};return [
 ['Материалы',s.materials],['Оплата бригад',s.labor],['Начисления на оплату труда',s.employmentCharges],['Механизация и аренда',s.machinery],['Доставка',s.delivery],['Прочие прямые расходы',s.other],['Прямые расходы',s.direct],['Накладные',s.overheads],['Себестоимость',s.cost],['Наценка / прибыль',s.profit],['Цена без НДС',s.beforeVat],['НДС',s.vat],['Цена для заказчика',s.total]
 ];}
function dashboard(){const p=project(),s=calc?.summary||{},rows=calc?.positions||[];let parts=[{n:'Материалы',v:s.materials||0},{n:'Оплата СМР',v:s.labor||0},{n:'Прочие и накладные',v:(s.cost||0)-(s.materials||0)-(s.labor||0)}];const cost=s.cost||1;
 return head('Контроль объекта',`Текущий объект: ${esc(p.name)}. Все суммы рассчитаны из введённых объёмов и расценок.`,`<button class="btn secondary" data-action="exportXlsx">↓ Excel</button>`)+alertBox()+
 `<div class="metrics">${metric('Позиции работ',p.lines.length,'строк в ведомости')}${metric('Материалы',rub(s.materials),'закупочная стоимость')}${metric('Оплата СМР',rub(s.labor),'выплаты исполнителям')}${metric('Цена предложения',rub(s.total),calc?.incomplete?'предварительная, есть пропуски':'из расчёта',true)}</div>`+
 `<div class="grid2">${panel('Структура себестоимости','Распределение затрат по введённым данным',`<div class="panel-body">${parts.map(a=>`<div class="legend"><span>${a.n}</span><b>${rub(a.v)}</b></div><div class="bar"><div style="width:${Math.max(0,Math.min(100,100*a.v/cost))}%"></div></div>`).join('')}<div class="divider"></div><div class="stat-list"><div class="stat-row"><span>Себестоимость</span><b>${rub(s.cost)}</b></div><div class="stat-row"><span>Наценка</span><b>${rub(s.profit)}</b></div><div class="stat-row"><span>Цена предложения с НДС</span><b>${rub(s.total)}</b></div></div></div>`,`<button class="btn tiny" data-view="estimate">Подробнее</button>`)}
 ${panel('Состояние расчёта','Проверка полноты данных',`<div class="panel-body"><div class="stat-row"><span>Позиции работ</span><b>${p.lines.length}</b></div><div class="stat-row"><span>Материалов в расчёте</span><b>${calc?.resources?.length||0}</b></div><div class="stat-row"><span>Замечаний к расчёту</span><b class="${calc?.issues?.length?'warning-value':''}">${calc?.issues?.length||0}</b></div><div class="stat-row"><span>Версия</span><b>№ ${p.version||1}</b></div><div class="divider"></div><p class="help">Нормативные базы ГЭСН, ФСНБ и ФГИС ЦС не подключены. Работа ведётся по введённым пользователем коммерческим данным.</p><div class="actions"><button class="btn secondary" data-view="vor">Открыть ВОР</button><button class="btn primary" data-view="estimate">Перейти к расчёту</button></div></div>`)}</div>`+
 panel('Позиции с наибольшей стоимостью','Материалы + оплата СМР, без распределения общих расходов',`<div class="table-scroll"><table><thead><tr><th>Работа</th><th>Объём</th><th class="num">Материалы</th><th class="num">Оплата работ</th><th class="num">Всего</th></tr></thead><tbody>${[...rows].sort((a,b)=>(b.materials+b.labor)-(a.materials+a.labor)).slice(0,6).map(r=>`<tr><td class="namecell">${esc(r.name)}</td><td>${qtyFmt(r.qty)} ${esc(r.unit)}</td><td class="num">${rub(r.materials)}</td><td class="num">${rub(r.labor)}</td><td class="num"><b>${rub(r.materials+r.labor)}</b></td></tr>`).join('')}</tbody></table></div>`);
}
function projects(){return head('Объекты','Независимые расчёты по каждому строительному объекту.',`<button class="btn primary" data-action="newProject">+ Создать объект</button>`)+`<div class="project-grid">${data.projects.map(p=>`<div class="project-card ${p.id===data.active?'current':''}"><span class="tag ${p.demo?'warn':'good'}">${p.demo?'Демо':'Рабочий объект'}</span><h3>${esc(p.name)}</h3><p>${esc(p.address||'Адрес не указан')}<br>Версия ${p.version||1} · ${esc(p.date||'Без даты')}</p><div class="actions"><button class="btn primary tiny" data-action="activate" data-id="${p.id}">${p.id===data.active?'Открыт':'Открыть'}</button><button class="btn tiny secondary" data-action="editProject" data-id="${p.id}">Изменить</button>${data.projects.length>1?`<button class="btn tiny danger" data-action="deleteProject" data-id="${p.id}">Удалить</button>`:''}</div></div>`).join('')}</div>`;}
function vor(){let p=project();return head('Ведомость объёмов работ','Работы и объёмы из проекта. Для корректного расчёта у каждой позиции укажите единицу измерения и количество.',`<button class="btn secondary" data-action="import">↑ Импорт PDF / Excel</button><button class="btn secondary" data-action="csv" data-csv="vor">↓ CSV</button><button class="btn primary" data-action="newLine">+ Добавить работу</button>`)+alertBox()+panel(`Ведомость · ${p.lines.length} позиций`,'Количества и материалы не генерируются системой автоматически',p.lines.length?`<div class="table-scroll"><table><thead><tr><th>№</th><th>Раздел</th><th>Наименование работы</th><th>Ед.</th><th class="num">Объём</th><th>Источник</th><th></th></tr></thead><tbody>${p.lines.map((l,i)=>`<tr><td class="muted">${i+1}</td><td>${esc(l.section||'—')}</td><td class="namecell">${esc(l.name)}</td><td>${esc(l.unit)}</td><td class="num">${qtyFmt(l.qty)}</td><td class="small muted">${esc(l.source||'Не указан')}</td><td><div class="table-actions">${l.sourceRef?`<button class="btn tiny secondary" data-action="viewSource" data-id="${l.id}">PDF</button>`:''}<button class="btn tiny secondary" data-action="editLine" data-id="${l.id}">Править</button><button class="btn tiny ghost" data-action="duplicateLine" data-id="${l.id}">Копия</button><button class="btn tiny danger" data-action="deleteLine" data-id="${l.id}">×</button></div></td></tr>`).join('')}</tbody></table></div>`:empty('Добавьте позицию вручную или импортируйте ведомость.',`<button class="btn primary" data-action="newLine">+ Добавить работу</button>`));}
function materials(){const rows=calc?.resources||[];const p=project();return head('Материальные ресурсы','Нормы расхода задаются вручную и привязываются к конкретным работам. Закупочное количество округляется вверх: для шт./компл. до целого, для остальных единиц до 0,001.',`<button class="btn secondary" data-action="csv" data-csv="materials">↓ CSV</button><button class="btn primary" data-view="catalog">Открыть справочник</button>`)+alertBox()+panel('Сводная потребность','Материалы группируются по названию и единице. Цены по объекту фиксируются при привязке и не меняются при редактировании общего справочника',rows.length?`<div class="table-scroll"><table><thead><tr><th>Материал</th><th>Ед.</th><th class="num">Количество</th><th class="num">Цена за ед.</th><th class="num">Стоимость</th><th>Проверка</th></tr></thead><tbody>${rows.map(r=>`<tr><td class="namecell">${esc(r.name)}</td><td>${esc(r.unit)}</td><td class="num">${qtyFmt(r.quantity)}</td><td class="num">${r.mixedPrices?'Разные цены':r.price===null?'Не задана':rub(r.price)}</td><td class="num"><b>${rub(r.cost)}</b></td><td>${r.missing?'<span class="tag warn">Уточнить</span>':r.mixedPrices?'<span class="tag warn">Несколько цен</span>':'<span class="tag good">Заполнено</span>'}</td></tr>`).join('')}</tbody></table></div>`:empty('Свяжите работы с материалами из справочника.'))+
 panel('Привязки материалов к работам','Норма расхода задаётся на одну единицу соответствующей работы.',p.lines.length?`<div class="panel-body">${p.lines.map(l=>`<div class="link-row"><div style="flex:1;min-width:180px"><b>${esc(l.name)}</b><div class="help">${qtyFmt(l.qty)} ${esc(l.unit)} · ${l.materials.length} материала</div></div><div class="small muted" style="flex:2;min-width:180px">${l.materials.map(m=>{let x=materialById(m.materialId);return `<span class="tag">${esc(m.materialName||x?.name||'Материал удалён')}: ${esc(m.norm??'нет нормы')} ${esc(m.materialUnit||x?.unit||'')}, ${m.price===null?'цена не задана':rub(m.price)}</span>`}).join(' ')||'Материалы пока не привязаны'}</div><button class="btn tiny secondary" data-action="manageLinks" data-id="${l.id}">Настроить</button></div>`).join('')}</div>`:empty('Сначала добавьте работы в ВОР.'));
}
function labor(){const p=project(),rows=calc?.positions||[];return head('Оплата строительно-монтажных работ','Сдельная ставка бригады × фактический объём работы. Это коммерческие выплаты, а не нормативная оплата труда по ГЭСН.',`<button class="btn secondary" data-action="csv" data-csv="labor">↓ CSV</button>`)+alertBox()+panel('Оплата исполнителям','Редактируйте ставки прямо в таблице; изменения сохраняются после выхода из поля',p.lines.length?`<div class="table-scroll"><table><thead><tr><th>Наименование работы</th><th>Ед.</th><th class="num">Объём</th><th class="num">Ставка за ед., ₽</th><th class="num">Оплата, ₽</th><th>Источник ставки</th></tr></thead><tbody>${p.lines.map((l,i)=>`<tr><td class="namecell">${esc(l.name)}</td><td>${esc(l.unit)}</td><td class="num">${qtyFmt(l.qty)}</td><td class="num"><input class="editable" aria-label="Ставка ${esc(l.name)}" data-rate="${l.id}" inputmode="decimal" value="${esc(l.laborRate??'') }" placeholder="Не задана"></td><td class="num"><b>${l.laborRate===''||l.laborRate===null||l.laborRate===undefined?'<span class="warning-value">Нет ставки</span>':rub(rows[i]?.labor||0)}</b></td><td class="small">${esc(l.laborSource||'Не указан')} <button class="btn tiny secondary" data-action="editLine" data-id="${l.id}">Уточнить</button></td></tr>`).join('')}</tbody><tfoot><tr><th colspan="4">Итого сдельная оплата</th><th class="num">${rub(calc?.summary?.labor)}</th><th></th></tr></tfoot></table></div>`:empty('Сначала добавьте работы в ВОР.'));
}
function extraField(label,key,suffix='₽'){return `<div class="field"><label for="extra_${key}">${label}, ${suffix}</label><input id="extra_${key}" data-extra="${key}" inputmode="decimal" value="${esc(project().extras?.[key]??0)}"></div>`;}
function estimate(){const s=calc?.summary||{};return head('Коммерческий расчёт','Фактическая себестоимость, прибыль и цена для заказчика. Наценка считается от себестоимости, накладные — от всех прямых расходов.',`<button class="btn secondary" data-action="csv" data-csv="estimate">↓ CSV</button><button class="btn secondary" data-view="history">История</button><button class="btn primary" data-action="exportXlsx">↓ Расчёт Excel</button>`)+alertBox()+`<div class="grid2">${panel('Параметры расчёта','Изменение значений обновляет расчёт',`<div class="panel-body"><div class="form-grid">${extraField('Механизация и аренда','machinery')}${extraField('Доставка / транспорт','delivery')}${extraField('Прочие прямые расходы','other')}${extraField('Начисления на оплату труда','employmentChargesPct','% от оплаты СМР')}${extraField('Накладные от прямых расходов','overheadPct','%')}${extraField('Наценка от себестоимости','markupPct','%')}<div class="field"><label>Режим НДС</label><select id="vatMode" data-vat-mode><option value="none" ${project().extras?.vatMode==='none'?'selected':''}>Без начисления НДС</option><option value="rate" ${project().extras?.vatMode==='rate'?'selected':''}>Начислять по ставке</option></select></div>${extraField('Ставка НДС','vatPct','% (при начислении)')}</div><div class="spacer"></div><p class="help">Режим и ставка НДС определяются бухгалтером; «Без начисления» не подтверждает освобождение от налога. Начисления на оплату труда включайте только если это соответствует вашей модели найма, не учитывайте их дважды.</p></div>`)}${panel('Итог по объекту',calc?.incomplete?'Предварительный итог: есть незаполненные данные':'Расчёт заполнен по введённым данным',`<div class="panel-body"><table class="summary-table"><tbody>${moneyCells(s).map(([n,v],i)=>`<tr class="${i===12?'total':''}"><td>${n}</td><td class="num">${rub(v)}</td></tr>`).join('')}</tbody></table></div>`)}</div>`+panel('Проверка перед выдачей предложения',calc?.issues?.length?`${calc.issues.length} замечаний`:'Блокирующих пропусков нет — проверьте предупреждения',calc?.issues?.length?`<div class="panel-body"><ul class="checklist">${calc.issues.map(x=>`<li>${esc(x)}</li>`).join('')}</ul></div>`:`<div class="panel-body"><span class="tag good">Формальные проверки пройдены</span><p class="small muted">Это не подтверждает соответствие фактическим ценам, проекту или нормативам. Перед использованием проверьте источники и договорные условия.</p></div>`);
}
function catalog(){return head('Справочник материалов','Собственный перечень ресурсов, цен и источников. Данные не подтягиваются из внешних прайс-листов.',`<button class="btn primary" data-action="newMaterial">+ Новый материал</button>`)+alertBox()+panel('Материалы и закупочные цены','Цены в рублях, дата и источник указываются вручную',data.catalog.length?`<div class="table-scroll"><table><thead><tr><th>Наименование</th><th>Ед.</th><th class="num">Цена за ед.</th><th>Актуальность</th><th>Поставщик / источник</th><th></th></tr></thead><tbody>${data.catalog.map(m=>`<tr><td class="namecell">${esc(m.name)}</td><td>${esc(m.unit)}</td><td class="num">${m.price===null||m.price===''?'Не задана':rub(m.price)}</td><td>${esc(m.date||'Не указана')}</td><td>${esc(m.source||'Не указан')}</td><td><div class="table-actions"><button class="btn tiny secondary" data-action="editMaterial" data-id="${m.id}">Изменить</button><button class="btn tiny danger" data-action="deleteMaterial" data-id="${m.id}">×</button></div></td></tr>`).join('')}</tbody></table></div>`:empty('Добавьте материал и закупочную цену.',`<button class="btn primary" data-action="newMaterial">+ Добавить</button>`));}
function history(){const p=project();const snapshots=p.snapshots||[];return head('История расчётов','Фиксируйте коммерческую стоимость и вводные на момент согласования. Применённые цены материалов включены в снимки.',`<button class="btn primary" data-action="snapshot">+ Зафиксировать текущий расчёт</button>`)+alertBox()+panel('Зафиксированные версии',`${snapshots.length} снимков (до 12 на объект)`,snapshots.length?`<div class="table-scroll"><table><thead><tr><th>Создан</th><th>Версия</th><th>Статус</th><th>Стоимость</th><th></th></tr></thead><tbody>${[...snapshots].reverse().map(x=>`<tr><td>${esc(x.at)}</td><td>${esc(x.version)}</td><td>${esc(x.status)}</td><td class="num">${rub(x.summary?.total)}</td><td><button class="btn tiny secondary" data-action="downloadSnapshot" data-id="${x.id}">Скачать JSON</button> <button class="btn tiny danger" data-action="deleteSnapshot" data-id="${x.id}">Удалить</button></td></tr>`).join('')}</tbody></table></div>`:empty('Зафиксированных версий пока нет. Сохраните снимок перед отправкой коммерческого предложения.'));}
function makeSnapshot(){if(window.smechWorkspace?.active)return window.smechWorkspace.snapshot();const p=project();if(!calc){toast('Нет актуального расчёта');return;}if(p.lines.length>2000){toast('Для больших ВОР скачайте резервную копию JSON — локальная история ограничена 2000 строками');return;}
 const copy=JSON.parse(JSON.stringify(p));delete copy.snapshots;const snap={id:uid(),at:new Date().toLocaleString('ru-RU'),version:p.version,status:calc.incomplete?'Предварительный':'Формально заполнен',summary:JSON.parse(JSON.stringify(calc.summary)),blockers:[...calc.blockers],project:copy};
 p.snapshots=p.snapshots||[];p.snapshots.push(snap);p.snapshots=p.snapshots.slice(-12);if(save()){view='history';paint();toast('Снимок сохранён на этом устройстве. Для надёжного архива скачайте JSON.');}}
function downloadSnapshot(id){if(window.smechWorkspace?.active)return window.smechWorkspace.downloadSnapshot(id);const x=(project().snapshots||[]).find(a=>a.id===id);if(x)download(new Blob([JSON.stringify({format:'smech-snapshot',version:2,snapshot:x},null,2)],{type:'application/json'}),`Смеч снимок ${x.id}.json`);}
function settings(){return head('Настройки и данные','Настройка режима хранения, доступов, резервирования и экспорта.')+(window.smechWorkspace?.settingsHtml()||'')+
 `${window.smechWorkspace?.active?'':`<div class="alert info"><b>Локальный режим.</b> Данные объектов хранятся в localStorage браузера. При его очистке они могут исчезнуть; регулярно сохраняйте резервную копию JSON.</div>`}`+
 panel('Резервные копии','Сохраняйте копию после каждого существенного изменения',`<div class="panel-body"><div class="settings-option"><div><b>Экспорт резервной копии</b><div class="help">Все объекты, ВОР, ставки и материалы в JSON</div></div><button class="btn primary" data-action="backup">Скачать JSON</button></div>${window.smechWorkspace?.active?'':`<div class="settings-option"><div><b>Восстановление резервной копии</b><div class="help">Заменит все данные этого браузера после подтверждения</div></div><label class="btn secondary" style="cursor:pointer">Загрузить JSON<input id="restoreFile" type="file" accept=".json,application/json" class="hide"></label></div>`}<div class="settings-option"><div><b>Выгрузить текущий объект в Excel</b><div class="help">ВОР, материалы, оплата СМР, коммерческий расчёт</div></div><button class="btn secondary" data-action="exportXlsx">Скачать XLSX</button></div></div>`)+
 panel('Ограничения версии 0.5','','<div class="panel-body small"><p>Поддерживается импорт XLSX, CSV, TSV. PDF и сканы обрабатываются локально с проверкой. Не поддерживаются старый формат .xls, BIM/IFC, автоматическое снятие объёмов с чертежей и получение коммерческих цен поставщиков.</p><p>ГЭСН, ФСНБ-2022 и ФГИС ЦС не подключены. Расчёт является коммерческим калькулятором, а не сметой по государственной методике.</p><p>Многопользовательское рабочее пространство доступно только при отдельном включении. Для промышленного развёртывания обязательны TLS, управление секретами, резервное копирование и аудит безопасности.</p></div>');}
function paint(){window.smechWorkspace?.updateHeader();document.querySelectorAll('#nav [data-view],.settings-btn').forEach(b=>b.classList.toggle('active',b.dataset.view===view));document.getElementById('crumb').textContent=VIEWS[view][0].toUpperCase();document.getElementById('topTitle').textContent=VIEWS[view][1];document.getElementById('projectSelect').innerHTML=data.projects.map(p=>`<option value="${p.id}" ${p.id===data.active?'selected':''}>${esc(p.name)}</option>`).join('');const page={dashboard,projects,vor,materials,labor,estimate,catalog,spec:()=>window.smechAdvanced.specView(),approvals:()=>window.smechAdvanced.reviewView(),history,settings}[view];document.getElementById('app').innerHTML=page();}
let calcSerial=0;
async function refresh(){save();const serial=++calcSerial;try{const response=await fetch('/api/calculate',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({project:project(),catalog:data.catalog})});if(!response.ok)throw Error('Невозможно выполнить расчёт');const result=await response.json();if(serial===calcSerial){calc=result;paint();}}catch(e){if(serial===calcSerial){calc=null;paint();toast('Ошибка расчёта: '+e.message);}}}
function openModal(title,intro,body,saveLabel,onSave){const dlg=document.getElementById('modal');dlg.classList.remove('pdf-wide');const inner=document.getElementById('modalInner');inner.innerHTML=`<form id="dialogForm"><h2>${title}</h2><p class="intro">${intro}</p>${body}<div class="modal-footer"><button type="button" class="btn secondary" data-action="closeModal">Отмена</button><button type="submit" class="btn primary">${saveLabel||'Сохранить'}</button></div></form>`;dlg.showModal();inner.querySelector('#dialogForm').addEventListener('submit',async e=>{e.preventDefault();try{const ok=await onSave(new FormData(e.currentTarget),e.currentTarget);if(ok===false)return;dlg.close();await refresh();}catch(err){toast(err.message)}});}
const field=(title,name,value='',type='text',extra='')=>`<div class="field"><label for="f_${name}">${title}</label><input id="f_${name}" name="${name}" type="${type}" value="${esc(value??'')}" ${extra}></div>`;
function projectDialog(id){const p=id?data.projects.find(x=>x.id===id):null;openModal(p?'Изменить объект':'Новый объект','Для реального объекта ведомость создаётся пустой. Никаких примерных цен система не подставляет.',`<div class="form-grid">${field('Название объекта','name',p?.name||'','','required')}${field('Дата расчёта','date',p?.date||today(),'date')}${field('Адрес','address',p?.address||'')}${field('Организация','organization',p?.organization||'')}</div>`,'Сохранить',fd=>{const name=String(fd.get('name')||'').trim();if(!name){toast('Введите название');return false;}if(p){p.name=name;p.date=fd.get('date');p.address=fd.get('address');p.organization=fd.get('organization');p.version++;}else{const v={id:uid(),name,date:fd.get('date'),address:fd.get('address'),organization:fd.get('organization'),demo:false,version:1,lines:[],specifications:[],extras:{machinery:0,delivery:0,other:0,employmentChargesPct:0,overheadPct:0,markupPct:0,vatMode:'none',vatPct:0}};data.projects.push(v);data.active=v.id;view='vor';}});}
function lineDialog(id){let p=project(),line=id?lineById(id):null;openModal(line?'Редактировать работу':'Добавить работу','Объём берите из ВОР или подтверждённого обмера.',`<div class="form-grid">${field('Наименование работы','name',line?.name||'','','required')}${field('Раздел','section',line?.section||'')}${field('Единица измерения','unit',line?.unit||'м²')}${field('Объём','qty',line?.qty??'','text','required inputmode="decimal"')}${field('Шифр / код','code',line?.code||'')}${field('Сдельная ставка, ₽ за ед.','laborRate',line?.laborRate??'','text','inputmode="decimal"')}${field('Источник сдельной ставки','laborSource',line?.laborSource||'')}${field('Дата ставки','laborDate',line?.laborDate||'','date')}${field('Источник / лист проекта','source',line?.source||'')}${field('Примечание','note',line?.note||'')}<div class="field span2"><label><input type="checkbox" name="materialRequired" ${line?.materialRequired?'checked':''} style="width:auto"> Для работы требуются материалы (если отметка снята, подтверждаю, что они не нужны)</label></div></div>`,'Сохранить',fd=>{const name=String(fd.get('name')||'').trim();const qty=fd.get('qty'),rate=fd.get('laborRate');if(!name||!isNumber(qty)){toast('Введите наименование и неотрицательный объём');return false;}if(String(rate).trim()&&!isNumber(rate)){toast('Ставка должна быть неотрицательным числом');return false;}const fields={name,section:fd.get('section'),unit:fd.get('unit'),qty:inputNum(qty),code:fd.get('code'),laborRate:rate===''?null:inputNum(rate),laborSource:fd.get('laborSource'),laborDate:fd.get('laborDate'),source:fd.get('source'),note:fd.get('note'),materialRequired:fd.has('materialRequired')};if(line)Object.assign(line,fields);else p.lines.push({id:uid(),...fields,materials:[]});p.version++;});}
function materialDialog(id){let m=id?materialById(id):null;openModal(m?'Изменить материал':'Новый материал','Укажите закупочную цену по подтверждённому предложению. Пустая цена останется незаполненной.',`<div class="form-grid">${field('Наименование','name',m?.name||'','','required')}${field('Единица','unit',m?.unit||'шт')}${field('Цена за ед., ₽','price',m?.price??'','text','inputmode="decimal"')}${field('Дата актуальности','date',m?.date||'','date')}${field('Поставщик / источник','source',m?.source||'')}</div>`,'Сохранить',fd=>{const name=String(fd.get('name')||'').trim(),price=fd.get('price');if(!name||String(price).trim()&&!isNumber(price)){toast('Проверьте наименование и цену');return false;}const obj={name,unit:fd.get('unit'),price:String(price).trim()===''?null:inputNum(price),date:fd.get('date'),source:fd.get('source')};if(m)Object.assign(m,obj);else data.catalog.push({id:uid(),...obj});project().version++;});}
function linksDialog(id){let l=lineById(id);if(!l)return;let options=data.catalog.map(m=>`<option value="${m.id}">${esc(m.name)} (${esc(m.unit)})</option>`).join('');const rows=l.materials.map(link=>{const mat=materialById(link.materialId);return `<div class="link-row"><div style="flex:1"><b>${esc(link.materialName||mat?.name||'Материал удалён')}</b><div class="help">Норма ${esc(link.norm??'—')} ${esc(link.materialUnit||mat?.unit||'')} · потери ${esc(link.waste||0)}% · цена ${link.price===null?'не указана':rub(link.price)} · ${esc(link.priceDate||'без даты')}</div><div class="help">Источник: ${esc(link.priceSource||'не указан')}</div></div><button class="btn tiny secondary" type="button" data-action="syncPrice" data-line="${l.id}" data-id="${link.id}">Обновить цену</button><button class="btn tiny danger" type="button" data-action="removeLink" data-line="${l.id}" data-id="${link.id}">Удалить</button></div>`}).join('');const dlg=document.getElementById('modal'),inner=document.getElementById('modalInner');inner.innerHTML=`<h2>Материалы для работы</h2><p class="intro">${esc(l.name)} · ${qtyFmt(l.qty)} ${esc(l.unit)}</p><div>${rows||'<p class="muted small">Нет привязанных материалов.</p>'}</div><div class="divider"></div>${data.catalog.length?`<form id="addLinkForm"><div class="form-grid"><div class="field span2"><label>Материал из справочника</label><select name="materialId" required>${options}</select></div>${field('Расход на единицу работы','norm','','text','required inputmode="decimal"')}${field('Потери, %','waste','0','text','inputmode="decimal"')}</div><div class="modal-footer"><button class="btn secondary" type="button" data-action="closeModal">Закрыть</button><button class="btn primary" type="submit">+ Добавить материал</button></div></form>`:`<p class="alert">Справочник материалов пуст. Сначала добавьте материал.</p><button class="btn secondary" data-action="closeModal">Закрыть</button>`}`;dlg.showModal();const form=inner.querySelector('#addLinkForm');if(form)form.addEventListener('submit',async e=>{e.preventDefault();const fd=new FormData(form);if(!isNumber(fd.get('norm'))||!isNumber(fd.get('waste'))){toast('Проверьте норму и процент потерь');return;}const mat=materialById(fd.get('materialId'));l.materials.push({id:uid(),materialId:mat.id,norm:inputNum(fd.get('norm')),waste:inputNum(fd.get('waste')),materialName:mat.name,materialUnit:mat.unit,price:mat.price,priceSource:mat.source,priceDate:mat.date});l.materialRequired=true;project().version++;dlg.close();await refresh();linksDialog(id);});}
function download(blob,filename){const a=document.createElement('a'),url=URL.createObjectURL(blob);a.href=url;a.download=filename;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function backup(){download(new Blob([JSON.stringify({format:'smech-backup',version:2,exportedAt:new Date().toISOString(),data},null,2)],{type:'application/json'}),'Смеч резервная копия.json');toast('Резервная копия сохранена');}
function csvSave(type){let rows=getRows(type);let text='\uFEFF'+rows.map(r=>r.map(x=>{let v=String(x??'');if(/^\s*[=+@\-]/.test(v)&&typeof x==='string')v="'"+v;return `"${v.replaceAll('"','""')}"`;}).join(';')).join('\r\n');download(new Blob([text],{type:'text/csv;charset=utf-8'}),`Смеч ${type}.csv`);}
function getRows(type){const p=project(),s=calc?.summary||{};if(type==='vor')return [['№','Раздел','Шифр','Наименование работ','Ед. изм.','Количество','Источник','Примечание'],...p.lines.map((l,i)=>[i+1,l.section,l.code,l.name,l.unit,Number(l.qty),l.source,l.note])];
 if(type==='spec')return [['Материал по спецификации','Ед.','Количество','Код','Источник'],...(p.specifications||[]).map(x=>[x.name,x.unit,Number(x.qty),x.code,x.source])];
 if(type==='comparison')return [['Материал','Ед.','Потребность','По спецификации','Разница','Статус'],...(calc?.specificationCheck?.rows||[]).map(x=>[x.name,x.unit,x.demand,x.specified,x.difference,x.status])];
 if(type==='materials')return [['Наименование материала','Ед. изм.','Количество к закупке','Цена за ед., ₽','Стоимость, ₽','Проверка'],...(calc?.resources||[]).map(r=>[r.name,r.unit,r.quantity,r.price,r.cost,r.missing?'Уточнить':'Заполнено'])];
 if(type==='labor')return [['№','Наименование работ','Ед. изм.','Количество','Ставка за ед., ₽','Оплата, ₽','Источник ставки','Дата ставки'],...(calc?.positions||[]).map((r,i)=>[i+1,r.name,r.unit,r.qty,r.rate,r.labor,r.laborSource,r.laborDate])];
 if(type==='sources')return [['Работа','Материал','Ед.','Норма на ед. работы','Потери %','К закупке','Цена, ₽','Стоимость, ₽','Источник цены','Дата цены'],...(calc?.positions||[]).flatMap(r=>r.consumption.map(c=>[r.name,c.material,c.unit,c.norm,c.waste,c.quantity,c.price,c.cost,c.priceSource,c.priceDate]))];
 if(type==='audit')return [['Проверка','Значение'],['Объект',p.name],['Дата расчёта',p.date],['Версия',p.version],['Блокирующих замечаний',calc?.blockers?.length||0],['Предупреждений',calc?.warnings?.length||0],...((calc?.blockers||[]).map(x=>['БЛОКИРУЕТ',x])),...((calc?.warnings||[]).map(x=>['ВНИМАНИЕ',x])),['Метод расчёта','Коммерческая калькуляция подрядчика; не нормативная смета по методике Минстроя'],['Округление материалов','Вверх по каждой позиции (шт/компл до целого; другие до 0,001)'],['Накладные','% от прямых затрат'],['Наценка','% от себестоимости'],['НДС','Режим '+String(p.extras?.vatMode||'none')+', процент вводится пользователем'],['Начисления на оплату труда','% от прямой сдельной оплаты, когда применимо']];
 return [['Коммерческий расчёт','Сумма, ₽'],...moneyCells(s),['Статус',calc?.incomplete?'Предварительный расчёт':'Проверено на заполненность'],['Объект',p.name],['Версия',p.version],['Дата',p.date],...((calc?.issues||[]).map(x=>['Замечание',x]))];}
async function excelExport(){let p=project(),types=[['ВОР','vor'],['Материалы','materials'],['Нормы и цены','sources'],['Оплата СМР','labor'],['Расчёт','estimate'],['Проверка','audit'],['Спецификация','spec'],['Сверка','comparison']];try{const response=await fetch('/api/export-xlsx',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({sheets:types.map(([name,t])=>({name,rows:getRows(t)}))})});if(!response.ok)throw Error(await response.text());download(await response.blob(),`Смеч ${p.name.replace(/[\\/:*?"<>|]/g,' ').slice(0,35)}.xlsx`);toast('Excel-книга сформирована');}catch(e){toast('Ошибка выгрузки Excel: '+e.message);}}
const importFields=[['name','Наименование работ'],['unit','Единица измерения'],['qty','Количество'],['section','Раздел'],['code','Шифр'],['source','Источник']];
function guessColumn(header,key){const rules={name:/наим|вид работ|описание работ/i,unit:/ед(\.|иница)?\s*изм|измерения/i,qty:/об[ъь][её]м|обьем|кол-?во|количество/i,section:/раздел|этап/i,code:/шифр|код|обоснование/i,source:/источник|лист|чертеж/i};return header.findIndex(x=>rules[key].test(String(x||'').trim()));}
function importModal(){importData=null;openModal('Импорт ведомости','Файл обрабатывается только на запущенном вами сервере «Смеч». Данные добавляются после проверки и подтверждения.',`<div class="field"><label>PDF, XLSX, CSV или TSV до 15 МБ</label><input id="uploadFile" type="file" accept=".pdf,.xlsx,.csv,.tsv" required></div><label class="help"><input type="checkbox" id="enableOCR" style="width:auto"> Разрешить локальное OCR сканированного PDF (требуется Tesseract с русским языком; медленнее, возможно ошибочное чтение цифр)</label><p class="help">PDF: не более 40 страниц, OCR до 10 страниц. PDF-файлы не отправляются во внешние сервисы. Нормы расхода, зарплаты и цены автоматически не создаются. Старый .xls не поддерживается.</p>`,'Отмена',()=>false);const dlg=document.getElementById('modal');dlg.querySelector('#dialogForm').addEventListener('submit',e=>{e.preventDefault();dlg.close();});}
async function importUploaded(file){if(!file)return;const fd=new FormData();fd.append('file',file);try{const ocr=document.getElementById('enableOCR')?.checked&&file.name.toLowerCase().endsWith('.pdf');const resp=await fetch('/api/import'+(ocr?'?ocr=true':''),{method:'POST',body:fd});let parsed=await resp.json();if(!resp.ok)throw Error(parsed.detail||'Не удалось прочитать файл');importData={file,sheets:parsed.sheets||[],sheetIndex:0,headerRow:0,filename:parsed.filename||file.name,sha256:parsed.sha256||'',pdf:parsed.sourceType==='pdf',warnings:parsed.warnings||[],selected:new Set(),edits:{},rowPage:0};renderImportMap();}catch(e){toast('Импорт: '+e.message);}}
function importMapping(){const result={};for(const [key] of importFields){const el=document.getElementById('map_'+key);result[key]=el?Number(el.value):-1;}return result;}
function pdfRowValues(sheet,index,mapping){const row=sheet.rows[index]||[];const get=k=>mapping[k]<0?'':String(row[mapping[k]]??'').trim();const edits=importData.edits[importData.sheetIndex+':'+index]||{};return {name:edits.name??get('name'),qty:edits.qty??get('qty'),unit:edits.unit??get('unit'),section:get('section'),code:get('code'),source:get('source')};}
function pdfIsValid(row){return !!row.name.trim()&&/^[\p{L}\d²³%.,\/()\s-]{1,24}$/u.test(row.unit.trim())&&isNumber(row.qty)&&Number(inputNum(row.qty))>0&&!/^(?:итого|всего|сумма\s*:)/i.test(row.name.trim());}
function renderPdfReviewTable(){if(!importData?.pdf)return;const s=importData.sheets[importData.sheetIndex],mapping=importMapping();if(!s)return;const wrap=document.getElementById('pdfReview');if(!wrap)return;const first=importData.headerRow+1,total=Math.max(0,s.rows.length-first),last=Math.max(0,Math.ceil(total/20)-1);importData.rowPage=Math.min(last,Math.max(0,importData.rowPage));const start=first+importData.rowPage*20;const indices=Array.from({length:Math.max(0,Math.min(20,s.rows.length-start))},(_,j)=>start+j);
 const good=Array.from({length:total},(_,j)=>first+j).filter(i=>pdfIsValid(pdfRowValues(s,i,mapping))).length;
 wrap.innerHTML=`<div class="alert"><b>Проверка PDF:</b> ${total} строк-кандидатов, ${good} с заполненными названием, единицей и положительным объёмом; выбрано ${importData.selected.size}. OCR и позиции, распознанные без границ таблицы, требуют сравнения с оригиналом. Ни одна строка не выбрана автоматически. Для OCR выбирайте строки вручную по одной после сверки.</div><div class="actions"><button type="button" class="btn tiny secondary" data-action="pdfSelectValid">Выбрать все корректные</button><button type="button" class="btn tiny secondary" data-action="pdfClearSelected">Снять выделение</button></div><div class="table-scroll"><table class="pdf-review-table"><thead><tr><th>Выбрать</th><th>Стр./строка</th><th>Наименование (можно править)</th><th>Ед.</th><th>Объём</th><th>Статус</th><th>Оригинал</th></tr></thead><tbody>${indices.map(i=>{const r=pdfRowValues(s,i,mapping),origin=s.origins?.[i]||{},valid=pdfIsValid(r);return `<tr><td><input type="checkbox" data-pdf-check="${i}" ${importData.selected.has(i)?'checked':''}></td><td class="small muted">${origin.page??'?'} / ${origin.row??i+1}${origin.method==='ocr-grid'?' · OCR':''}</td><td><input class="pdf-cell" aria-label="Наименование работы" data-pdf-edit="name" data-row="${i}" value="${esc(r.name)}"></td><td><input class="pdf-cell" aria-label="Единица измерения" data-pdf-edit="unit" data-row="${i}" value="${esc(r.unit)}"></td><td><input class="pdf-cell" aria-label="Объём" data-pdf-edit="qty" data-row="${i}" value="${esc(r.qty)}"></td><td>${valid?(origin.method==='ocr-grid'?'<span class="tag warn">Сверить OCR</span>':'<span class="tag good">Проверить</span>'):'<span class="tag warn">Исправить</span>'}</td><td><button class="btn tiny secondary" type="button" data-action="pdfSource" data-id="${i}">Показать</button></td></tr>`}).join('')}</tbody></table></div><div id="sourcePreview" class="pdf-source-preview"></div><div class="actions"><button type="button" class="btn tiny secondary" data-action="pdfPrev" ${importData.rowPage===0?'disabled':''}>← Предыдущие</button><span class="help">Страница просмотра ${importData.rowPage+1} из ${last+1}</span><button type="button" class="btn tiny secondary" data-action="pdfNext" ${importData.rowPage===last?'disabled':''}>Следующие →</button></div>`;
}
function renderImportMap(){if(!importData)return;const sheets=importData.sheets;if(!sheets.length){document.getElementById('modalInner').innerHTML=`<h2>Таблицы не найдены</h2><p class="intro">${esc(importData.filename||'PDF')}</p><div class="alert">${(importData.warnings||[]).map(esc).join(' ')||'Ни одна таблица не распознана.'} Автоматический импорт невозможен; попробуйте более качественный PDF или XLSX.</div><div class="modal-footer"><button class="btn secondary" data-action="closeModal">Закрыть</button></div>`;return;}
 const s=sheets[importData.sheetIndex]||sheets[0],rows=s.rows||[];if(!rows.length){toast('В таблице нет строк');return;}let hi=Math.min(importData.headerRow,Math.max(0,rows.length-1));const header=rows[hi]||[];const maxcols=Math.min(80,Math.max(6,...rows.slice(0,30).map(r=>r.length)));const choices=Array.from({length:maxcols},(_,i)=>`<option value="${i}">${i+1}: ${esc(header[i]||'(без названия)')}</option>`).join('');const mapping=importFields.map(([key,label])=>`<div class="field"><label>${label}${['name','qty'].includes(key)?' *':''}</label><select id="map_${key}"><option value="-1">— Не импортировать —</option>${choices}</select></div>`).join('');const preview=rows.slice(hi,Math.min(rows.length,hi+7));const warnings=[...(importData.warnings||[]),...(s.warnings||[])];const html=`<h2>Проверка столбцов${importData.pdf?' PDF':''}</h2><p class="intro">${esc(importData.filename)} · ${rows.length} строк. Укажите заголовки, проверьте распознанные значения. Повторы не удаляются.</p>${warnings.length?`<div class="alert">${warnings.map(esc).join(' ')}</div>`:''}<div class="form-grid"><div class="field"><label>${importData.pdf?'Таблица PDF':'Лист книги'}</label><select id="sheetIndex">${sheets.map((sheet,i)=>`<option value="${i}" ${i===importData.sheetIndex?'selected':''}>${esc(sheet.name)}</option>`).join('')}</select></div><div class="field"><label>Строка с заголовками</label><select id="headerRow">${Array.from({length:Math.min(20,rows.length)},(_,i)=>`<option value="${i}" ${i===hi?'selected':''}>Строка ${i+1}</option>`).join('')}</select></div></div><div class="mapping">${mapping}</div>${importData.pdf?'<div id="pdfReview"></div>':`<div class="preview-table"><table><tbody>${preview.map((r,i)=>`<tr>${r.slice(0,12).map(v=>`<${i===0?'th':'td'}>${esc(v)}</${i===0?'th':'td'}>`).join('')}</tr>`).join('')}</tbody></table></div>`}<div class="modal-footer"><button class="btn secondary" data-action="closeModal">Отмена</button><button class="btn primary" data-action="confirmImport">${importData.pdf?'Подтверждаю проверку: импортировать выбранные':'Импортировать строки'}</button></div>`;
 const dlg=document.getElementById('modal');dlg.classList.toggle('pdf-wide',!!importData.pdf);document.getElementById('modalInner').innerHTML=html;if(!dlg.open)dlg.showModal();for(const [key] of importFields){document.getElementById('map_'+key).value=String(guessColumn(header,key));}if(importData.pdf)renderPdfReviewTable();}
function confirmImport(){if(!importData)return;
 if(importData.pdf){const p=project(),s=importData.sheets[importData.sheetIndex],mapping=importMapping();if(mapping.name<0||mapping.qty<0||mapping.unit<0){toast('Для PDF укажите столбцы: работа, единица измерения и объём');return;}const selected=Array.from(importData.selected).sort((a,b)=>a-b).filter(i=>i>importData.headerRow&&i<s.rows.length);if(!selected.length){toast('Отметьте проверенные строки для импорта');return;}const prepared=[];for(const i of selected){const r=pdfRowValues(s,i,mapping);if(!pdfIsValid(r)){toast(`Ошибка в строке ${i+1}. Исправьте название, единицу измерения и объём.`);return;}const origin=s.origins?.[i]||{};const provenance=`PDF ${importData.filename}, стр. ${origin.page??'?'}, таблица ${origin.table??'?'}, строка ${origin.row??i+1}; SHA-256 ${importData.sha256}`;prepared.push({id:uid(),name:r.name,section:r.section,code:r.code,unit:r.unit,qty:inputNum(r.qty),source:(provenance+(r.source?'; '+r.source:'' )).slice(0,500),sourceRef:{file:importData.filename,sha256:importData.sha256,page:origin.page,table:origin.table,row:origin.row,rowBbox:origin.rowBbox},note:origin.method==='ocr-grid'?'OCR: пользователь подтвердил перенос строки, сверка с оригиналом обязательна':'Импортировано из PDF; сверить с оригиналом',materialRequired:null,laborRate:null,laborSource:'',laborDate:'',materials:[]});}if(p.lines.length+prepared.length>10000){toast('Превышен предел 10 000 строк ВОР');return;}
 if(!confirm(`Вы проверили ${prepared.length} строк PDF по оригиналу? Добавить их в объект «${p.name}»? Нормы, расценки и материалы останутся пустыми.`))return;
 p.lines.push(...prepared);p.version++;document.getElementById('modal').close();view='vor';importData=null;refresh();toast(`Импортировано проверенных строк PDF: ${prepared.length}. Источник и страницы сохранены.`);return;}
const p=project();const s=importData.sheets[importData.sheetIndex],mapping={};for(const [key]of importFields)mapping[key]=Number(document.getElementById('map_'+key).value);if(mapping.name<0||mapping.qty<0){toast('Укажите колонки с наименованием и количеством');return;}let imported=0,skipped=0;const duplicates=new Set(p.lines.map(l=>[l.name,l.unit,l.section,l.code,l.source].join('|').toLowerCase()));let possibleDuplicates=0;for(const row of s.rows.slice(importData.headerRow+1)){const get=key=>mapping[key]<0?'':String(row[mapping[key]]??'').trim();const name=get('name'),qty=get('qty'),unit=get('unit');if(!name||/^итого|всего|сумма\s*:/i.test(name)||!isNumber(qty)||Number(inputNum(qty))===0){skipped++;continue;}const signature=[name,unit,get('section'),get('code'),get('source')].join('|').toLowerCase();if(duplicates.has(signature))possibleDuplicates++;duplicates.add(signature);p.lines.push({id:uid(),name,section:get('section'),code:get('code'),unit,qty:inputNum(qty),source:get('source'),note:'Импортировано; нормы и ставка не заданы',materialRequired:null,laborRate:null,laborSource:'',laborDate:'',materials:[]});imported++;}p.version++;document.getElementById('modal').close();view='vor';refresh();toast(`Импортировано: ${imported}, пропущено пустых/некорректных: ${skipped}, возможных дублей: ${possibleDuplicates}. Укажите источники, ставки и нужность материалов.`);}
async function restoreFile(file){if(window.smechWorkspace?.active){toast('В рабочем пространстве используйте действие «Импорт локальных данных» в настройках');return;}try{const json=JSON.parse(await file.text());if(json.format!=='smech-backup'||!Array.isArray(json.data?.projects)||!Array.isArray(json.data?.catalog))throw Error('Это не резервная копия «Смеч»');const restored=normalizeData(json.data);if(!confirm('Все текущие данные браузера будут заменены из резервной копии. Продолжить?'))return;data=restored;storageLocked=false;loadError='';view='dashboard';await refresh();toast('Резервная копия восстановлена');}catch(e){toast('Не удалось восстановить: '+e.message);}}
async function handleAction(action,id,b){if(action.startsWith('ws')&&window.smechWorkspace)return window.smechWorkspace.action(action,id,b);const p=project();if(window.smechAdvanced?.action && await window.smechAdvanced.action(action,id,b))return;switch(action){case 'snapshot':makeSnapshot();break;case 'downloadSnapshot':downloadSnapshot(id);break;case 'deleteSnapshot':if(window.smechWorkspace?.active){toast('Архивные снимки рабочего пространства неизменяемы');break;}if(confirm('Удалить зафиксированный снимок?')){p.snapshots=(p.snapshots||[]).filter(x=>x.id!==id);await refresh();}break;case 'downloadDamaged':download(new Blob([localStorage.getItem(STORE)||''],{type:'application/json'}),'Смеч поврежденная копия.json');break;case 'resetDamaged':if(confirm('Старые повреждённые данные будут потеряны! Вы скачали исходную копию?')){localStorage.removeItem(STORE);storageLocked=false;loadError='';data=seed();await refresh();}break;case 'syncPrice':{const ln=lineById(b.dataset.line);const link=ln?.materials.find(x=>x.id===id);const mat=link?materialById(link.materialId):null;if(!mat){toast('Материал отсутствует в справочнике');return;}if(confirm('Обновить цену, дату и источник этой привязки из справочника? Текущая стоимость объекта изменится.')){Object.assign(link,{price:mat.price,priceDate:mat.date,priceSource:mat.source});p.version++;document.getElementById('modal').close();await refresh();linksDialog(ln.id);}break;}case 'newProject':projectDialog();break;case 'editProject':projectDialog(id);break;case 'activate':data.active=id;view='dashboard';await refresh();break;case 'deleteProject':if(data.projects.length<2)return;if(confirm('Удалить объект и все его расчёты без возможности восстановления?')){data.projects=data.projects.filter(x=>x.id!==id);if(data.active===id)data.active=data.projects[0].id;await refresh();}break;case 'newLine':lineDialog();break;case 'editLine':lineDialog(id);break;case 'deleteLine':if(confirm('Удалить позицию ведомости и все привязанные к ней материалы?')){p.lines=p.lines.filter(x=>x.id!==id);p.version++;await refresh();}break;case 'duplicateLine':{const original=lineById(id);if(!original)return;let dup=JSON.parse(JSON.stringify(original));dup.id=uid();dup.name+=' (копия)';dup.materials=dup.materials.map(l=>({...l,id:uid()}));p.lines.push(dup);p.version++;await refresh();break;}case 'newMaterial':materialDialog();break;case 'editMaterial':materialDialog(id);break;case 'deleteMaterial':if(confirm('Удалить материал? Все привязки к нему станут некорректными.')){data.catalog=data.catalog.filter(x=>x.id!==id);await refresh();}break;case 'manageLinks':linksDialog(id);break;case 'removeLink':{let l=lineById(b.dataset.line);if(l){l.materials=l.materials.filter(m=>m.id!==id);p.version++;document.getElementById('modal').close();await refresh();linksDialog(l.id);}break;}case 'closeModal':document.getElementById('modal').close();break;case 'import':importModal();break;case 'confirmImport':confirmImport();break;case 'pdfPrev':if(importData?.pdf){importData.rowPage--;renderPdfReviewTable();}break;case 'pdfNext':if(importData?.pdf){importData.rowPage++;renderPdfReviewTable();}break;case 'pdfSelectValid':if(importData?.pdf){const sheet=importData.sheets[importData.sheetIndex],m=importMapping();for(let i=importData.headerRow+1;i<sheet.rows.length;i++)if(sheet.origins?.[i]?.method!=='ocr-grid'&&pdfIsValid(pdfRowValues(sheet,i,m)))importData.selected.add(i);renderPdfReviewTable();}break;case 'pdfClearSelected':if(importData?.pdf){importData.selected.clear();renderPdfReviewTable();}break;case 'exportXlsx':await excelExport();break;case 'csv':csvSave(b.dataset.csv);break;case 'backup':backup();break;}}
document.addEventListener('click',e=>{let b=e.target.closest('button[data-action],button[data-view]');if(!b)return;const action=b.dataset.action;if(action)handleAction(action,b.dataset.id,b);else if(b.dataset.view){view=b.dataset.view;document.getElementById('sidebar').classList.remove('open');paint();}});
document.addEventListener('change',async e=>{const el=e.target,p=project();if(el.id==='projectSelect'){data.active=el.value;await refresh();return;}if(el.id==='uploadFile'){await importUploaded(el.files?.[0]);return;}if(el.id==='restoreFile'){await restoreFile(el.files?.[0]);return;}if(el.id==='sheetIndex'&&importData){importData.sheetIndex=Number(el.value);importData.headerRow=0;importData.selected.clear();importData.edits={};importData.rowPage=0;renderImportMap();return;}if(el.id==='headerRow'&&importData){importData.headerRow=Number(el.value);importData.selected.clear();importData.edits={};importData.rowPage=0;renderImportMap();return;}if(el.id?.startsWith('map_')&&importData?.pdf){importData.selected.clear();importData.edits={};importData.rowPage=0;renderPdfReviewTable();return;}if(el.dataset.pdfCheck!==undefined&&importData?.pdf){const idx=Number(el.dataset.pdfCheck);if(el.checked)importData.selected.add(idx);else importData.selected.delete(idx);return;}if(el.dataset.pdfEdit&&importData?.pdf){const key=importData.sheetIndex+':'+el.dataset.row;importData.edits[key]=importData.edits[key]||{};importData.edits[key][el.dataset.pdfEdit]=el.value;return;}if(el.dataset.vatMode!==undefined){p.extras.vatMode=el.value;p.version++;await refresh();return;}if(el.dataset.rate){let l=lineById(el.dataset.rate);if(!l)return;if(el.value.trim()&&!isNumber(el.value)){toast('Введите корректную неотрицательную ставку');el.value=l.laborRate??'';return;}l.laborRate=el.value.trim()===''?null:inputNum(el.value);p.version++;await refresh();return;}if(el.dataset.extra){if(!isNumber(el.value)){toast('Введите неотрицательное число');el.value=p.extras[el.dataset.extra]??0;return;}p.extras[el.dataset.extra]=inputNum(el.value);p.version++;await refresh();}});
document.getElementById('menuToggle').addEventListener('click',()=>document.getElementById('sidebar').classList.toggle('open'));
refresh();
